	for i in range(8):
		scene._end_day()
		await process_frame
	print("FINISHED=", scene.finished, " NATURE=", scene._average("nature"), " PEOPLE=", scene._average("people"), " OVERLAY=", scene.result_overlay != null)
	quit()

