extends SceneTree
func _initialize() -> void: call_deferred("_run")
func _run() -> void:
	var packed: PackedScene = load("res://main.tscn")
	var scene: Node = packed.instantiate()
	root.add_child(scene)
	await process_frame
	var plan := [[[0,3],[1,5]],[[0,1],[1,2]],[[0,4],[1,6]],[[0,6],[1,3]],[[0,2],[1,0]],[[0,0],[1,1]],[[0,5],[1,4]]]
	for pair in plan:
		for action in pair:
			scene.call("_select_action", action[0]); scene.call("_apply_action", action[1])
		scene.call("_end_day")
	scene.call("_end_day")
	await process_frame
	print("FINISHED=", scene.get("finished"), " OVERLAY=", scene.get("result_overlay") != null)
	quit()

extends SceneTree
func _initialize() -> void: call_deferred("_run")
func _run() -> void:
	var packed: PackedScene = load("res://main.tscn")
	var scene: Node = packed.instantiate()
	root.add_child(scene)
	await process_frame
	for i in range(8): scene.call("_end_day")
	await process_frame
	scene.call("_restart")
	await process_frame
	print("RESTART_DAY=", scene.get("day"), " ENERGY=", scene.get("energy"), " BUTTONS=", scene.get("action_buttons").size())
	quit()
